SELECT DISTINCT date FROM checkin 
WHERE user_id = #{userId} 
AND YEAR(date) = #{year} 
AND MONTH(date) = #{month}

SELECT * FROM checkin 
WHERE task_id = #{taskId} AND date = #{date}
LIMIT 1

SELECT COUNT(DISTINCT date) FROM checkin 
WHERE user_id = #{userId}
AND status = 'approved'

SELECT * FROM checkin 
WHERE user_id = #{userId} 
ORDER BY checkin_time DESC 
LIMIT #{limit}

mapper.update:
UPDATE checkin SET status = #{status}, partner_id = #{partnerId},
review_comment = #{reviewComment}, review_time = NOW()
WHERE id = #{id}
